# ---- Substitution function ----
function Expand-Vars([string]$text) {
  return [regex]::Replace($text, '\{\{([A-Z0-9_]+)\}\}', {
    param($m)
    $name = $m.Groups[1].Value
    if ($vars.ContainsKey($name)) { return [string]$vars[$name] }
    return $m.Value  # leave unknown placeholders intact (they are user-fill examples)
  })
}

# ---- Path mapping ----
# Maps a template-relative path under $TEMPLATES to a workspace-relative output path.
function Map-Path([string]$rel) {
  $rel = $rel.TrimStart('\','/')
  $rel = $rel -replace '\\','/'
  # Drop trailing .tmpl
  if ($rel.EndsWith('.tmpl')) { $rel = $rel.Substring(0, $rel.Length - 5) }

  # foundation/AGENTS.md -> AGENTS.md (root)
  if ($rel -eq 'foundation/AGENTS.md') { return 'AGENTS.md' }
  # foundation/copilot-instructions.md -> .github/copilot-instructions.md
  if ($rel -eq 'foundation/copilot-instructions.md') { return '.github/copilot-instructions.md' }
  # foundation/constitution.instructions.md -> .github/instructions/constitution.instructions.md
  if ($rel -eq 'foundation/constitution.instructions.md') { return '.github/instructions/constitution.instructions.md' }

  # harness-config.yaml -> .autoharness/config.yaml
  if ($rel -eq 'harness-config.yaml') { return '.autoharness/config.yaml' }

  # instructions/* -> .github/instructions/*
  if ($rel -like 'instructions/*') { return ".github/$rel" }

  # agents/* -> .github/agents/* (preserves review/, research/ subdirs)
  if ($rel -like 'agents/*') { return ".github/$rel" }

  # skills/* -> .github/skills/*
  if ($rel -like 'skills/*') { return ".github/$rel" }

  # policies/workflow-policies.md -> .github/policies/workflow-policies.md
  if ($rel -like 'policies/*') { return ".github/$rel" }

  # prompts/* -> .github/prompts/*
  if ($rel -like 'prompts/*') { return ".github/$rel" }

  # scripts/* -> scripts/autoharness/*
  if ($rel -like 'scripts/*') {
    $name = $rel.Substring('scripts/'.Length)
    return "scripts/autoharness/$name"
  }

  # backlog/config.yml -> .backlog/config.yml
  if ($rel -eq 'backlog/config.yml') { return '.backlog/config.yml' }
  # backlog/stash.md -> .backlog/.stash.md
  if ($rel -eq 'backlog/stash.md') { return '.backlog/.stash.md' }
  # backlog/registries/* -> NOT installed (read-only by installer)
  if ($rel -like 'backlog/registries/*') { return $null }

  return $null  # unmapped → skip
}

# ---- Walk templates ----
$installed = New-Object System.Collections.Generic.List[string]
$skipped = New-Object System.Collections.Generic.List[string]

Get-ChildItem -Path $TEMPLATES -Recurse -File | ForEach-Object {
  $full = $_.FullName
  $rel = $full.Substring($TEMPLATES.Length + 1)
  $outRel = Map-Path $rel
  if (-not $outRel) {
    $skipped.Add($rel) | Out-Null
    return
  }

  $outFull = Join-Path $WS $outRel
  $outDir = Split-Path $outFull -Parent
  if (-not (Test-Path $outDir)) { New-Item -ItemType Directory -Path $outDir -Force | Out-Null }

  if ($_.Extension -eq '.tmpl') {
    $content = Get-Content -Path $full -Raw -Encoding UTF8
    $expanded = Expand-Vars $content
    Set-Content -Path $outFull -Value $expanded -Encoding UTF8 -NoNewline:$false
  } else {
    Copy-Item -Path $full -Destination $outFull -Force
  }
  $installed.Add($outRel) | Out-Null
}

# ---- Backlog scaffolding (queue + archive dirs) ----
$backlogDirs = @('.backlog/queue', '.backlog/archive')
foreach ($d in $backlogDirs) {
  $p = Join-Path $WS $d
  if (-not (Test-Path $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null }
  $gk = Join-Path $p '.gitkeep'
  if (-not (Test-Path $gk)) { New-Item -ItemType File -Path $gk -Force | Out-Null }
  $installed.Add("$d/.gitkeep") | Out-Null
}

